style.css:
@-moz-document domain("chatgpt.com") {
/* Diagnostic revision: disables theme backdrop filters to isolate viewer occlusion. */

/* 01. New (2026) theme tokens plus older compatibility tokens. */
html, html[data-theme="light"], html[data-theme="dark"] {
  color-scheme: dark !important;
  --font-sans: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
  --font-mono: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
  --text-primary: #d9ffe6 !important;
  --text-secondary: #9ee5b6 !important;
  --text-tertiary: #70b68b !important;
  --text-quaternary: #5b9e74 !important;
  --text-inverted: #021108 !important;
  --bg-primary: transparent !important;
  --bg-secondary: rgba(2,26,12,.82) !important;
  --bg-tertiary: rgba(6,46,22,.84) !important;
  --bg-secondary-surface: rgba(1,22,10,.75) !important;
  --bg-elevated-primary: rgba(2,23,11,.97) !important;
  --bg-elevated-secondary: rgba(4,32,15,.97) !important;
  --bg-tooltip: rgba(1,20,10,.97) !important;
  --main-surface-primary: transparent !important;
  --main-surface-secondary: rgba(3,30,14,.75) !important;
  --main-surface-tertiary: rgba(4,39,18,.82) !important;
  --sidebar-surface: rgba(3,33,17,.47) !important;
  --sidebar-surface-primary: rgba(3,35,18,.41) !important;
  --sidebar-surface-secondary: rgba(4,45,22,.49) !important;
  --sidebar-surface-tertiary: rgba(6,56,28,.57) !important;
  --composer-surface-primary: rgba(3,38,21,.46) !important;
  --border-light: rgba(32,243,107,.18) !important;
  --border-default: rgba(28,240,102,.36) !important;
  --border-medium: rgba(45,255,118,.50) !important;
  --border-heavy: rgba(75,255,140,.62) !important;
  --icon-secondary: #7fffac !important;
  --icon-tertiary: #5dd98d !important;
  --interactive-bg-secondary-hover: rgba(12,91,39,.56) !important;
  --interactive-bg-secondary-press: rgba(10,115,43,.61) !important;
  --interactive-border-focus: #00ff66 !important;
  --surface-hover: rgba(16,104,45,.47) !important;
  --theme-user-msg-bg: rgba(4,54,27,.58) !important;
  --theme-user-msg-text: #d9ffe6 !important;
  --theme-submit-btn-bg: #00ed61 !important;
  --theme-submit-btn-text: #001708 !important;
  --theme-secondary-btn-bg: rgba(4,57,26,.88) !important;
  --theme-secondary-btn-text: #d9ffe6 !important;
  --color-surface: transparent !important;
  --color-surface-secondary: rgba(2,28,13,.80) !important;
  --color-surface-elevated-secondary: rgba(2,25,11,.97) !important;
  --color-background-panel: rgba(2,25,11,.80) !important;
  --color-background-control-opaque: rgba(4,43,20,.95) !important;
  --color-background-composer-surface: rgba(3,40,21,.45) !important;
  --color-background-composer-action-bar: rgba(3,40,20,.53) !important;
  --color-background-callout-surface: rgba(4,38,17,.91) !important;
  --color-background-mode-toggle-track: rgba(3,29,14,.91) !important;
  --color-background-mode-toggle-selected: rgba(8,73,34,.95) !important;
  --color-text-mode-toggle-inactive: #81c99a !important;
  --color-text-mode-toggle-primary: #d9ffe6 !important;
  --color-text-button-outline: #b7ffce !important;
  --color-border-button-outline: rgba(43,255,115,.44) !important;
  --color-background-button-outline-hover: rgba(14,92,43,.63) !important;
  --color-background-primary-ghost-hover: rgba(37,255,110,.14) !important;
  --color-background-primary-solid: #00e85c !important;
  --color-background-primary-solid-hover: #38ff87 !important;
  --color-background-primary-solid-active: #00c84c !important;
  --color-text-primary-solid: #001b09 !important;
  --color-background-composer-primary: #00e95d !important;
  --color-text-composer-primary: #001a08 !important;
  --color-text: #d9ffe6 !important;
  --color-text-emphasis: #eafff0 !important;
  --color-text-prose: #c8f8d9 !important;
  --color-text-primary: #d9ffe6 !important;
  --color-text-secondary: #a2e2b8 !important;
  --color-text-tertiary: #78bf96 !important;
  --alpha-base: #d9ffe6 !important;
  background-color: #0a0a0a !important;
  /* Entirely CSS-generated wallpaper: no image URLs or encoded assets. */
  /* Thin pale-green grid at 40px intervals, plus faint 4px CRT scan lines. */
  background-image:
    linear-gradient(to right, rgba(130,255,167,.13) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(130,255,167,.13) 1px, transparent 1px),
    repeating-linear-gradient(to bottom,
      rgba(10,10,10,0) 0px,
      rgba(10,10,10,0) 3px,
      rgba(105,255,153,.035) 3px,
      rgba(105,255,153,.035) 4px) !important;
  background-size: 40px 40px, 40px 40px, 100% 4px !important;
  background-position: 0 0 !important;
  background-repeat: repeat !important;
  background-attachment: fixed !important;
}

/* 02. Keep the CSS grid visible through the application's main canvas. */
html body, body, #root, #__next, main, #main, #thread,
[data-testid="conversation-container"],
[data-testid="conversation-panel"],
.bg-token-main-surface-primary, .bg-token-bg-primary {
  background-color: transparent !important;
}
body, #root, #__next {
  color: #d9ffe6 !important;
}
/* Terminal type without overriding icon fonts or mathematical glyphs. */
html, body,
body button, body input, body textarea, body select,
body [contenteditable="true"], body [role="textbox"],
body nav, body aside, body header,
body [role="dialog"], body [role="menu"],
body .prose, body .markdown, body [data-message-author-role] {
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
  font-variant-ligatures: none !important;
  font-feature-settings: "zero" 1 !important;
}
body nav, body aside, body header, body button,
body input, body textarea, body [contenteditable="true"] {
  letter-spacing: .012em !important;
}
::selection { background: rgba(0,255,102,.35) !important; color: #f5fff7 !important; }

/* 03. Sidebar: layered frosted emerald glass, with clear inner surfaces. */
#stage-slideover-sidebar, #sidebar,
[data-testid="sidebar"], [data-testid="sidebar-container"],
aside {
  background-color: rgba(2,24,13,.43) !important;
  background-image: linear-gradient(145deg,
    rgba(13,92,47,.35) 0%,
    rgba(4,47,25,.28) 40%,
    rgba(1,19,11,.59) 100%) !important;
  border-right: 1px solid rgba(67,255,134,.65) !important;
  border-radius: 0 19px 19px 0 !important;
  box-shadow:
    inset -1px 0 0 rgba(120,255,164,.22),
    inset 0 1px 0 rgba(168,255,190,.19),
    5px 0 24px rgba(0,225,88,.13) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
/* Avoid opaque, stacked backgrounds hiding the glass on inner sidebar rails. */
#stage-slideover-sidebar [class*="bg-token-sidebar-surface"],
#sidebar [class*="bg-token-sidebar-surface"],
[data-testid="sidebar"] [class*="bg-token-sidebar-surface"],
[data-testid="sidebar-container"] [class*="bg-token-sidebar-surface"],
aside [class*="bg-token-sidebar-surface"] {
  background-color: transparent !important;
  background-image: none !important;
}
.bg-token-sidebar-surface-primary,
.bg-token-sidebar-surface,
[data-testid="chat-history"],
nav[aria-label="Chat history"] {
  background-color: rgba(2,37,20,.19) !important;
  border-color: rgba(24,255,105,.20) !important;
}
/* Glass-tinted rows preserve selected/hover state and legible chat titles. */
[data-sidebar-item], .__menu-item[data-sidebar-item],
nav a, aside a, [data-testid="chat-history"] a {
  color: #c0ffd5 !important;
  border-radius: 10px !important;
}
[data-sidebar-item]:hover, .__menu-item[data-sidebar-item]:hover,
nav a:hover, aside a:hover, [data-testid="chat-history"] a:hover {
  background-color: rgba(17,117,53,.40) !important;
  color: #effff4 !important;
  box-shadow: inset 2px 0 0 rgba(0,255,102,.76),
              0 0 10px rgba(0,255,102,.09) !important;
}
.__menu-item[data-sidebar-item] {
  --menu-item-highlighted: rgba(12,104,45,.47) !important;
  --menu-item-active: rgba(12,106,47,.55) !important;
  --menu-item-open: rgba(12,106,47,.55) !important;
}

/* 04. Navigation headers and account strip. */
header:not([data-testid="viewer-header"]), #page-header,
[data-testid="conversation-header"],
[data-testid="app-shell-header-context-menu-surface"] {
  background-color: rgba(1,20,9,.58) !important;
  border-color: rgba(24,241,106,.22) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* 05. Ask ChatGPT composer: one visible glass shell, no doubled borders. */
#composer-background,
[data-testid="composer-background"] {
  background-color: rgba(2,33,18,.42) !important;
  background-image: linear-gradient(125deg,
    rgba(21,100,54,.40) 0%,
    rgba(7,55,30,.28) 48%,
    rgba(1,20,13,.60) 100%) !important;
  border: 1px solid rgba(85,255,143,.73) !important;
  border-radius: 26px !important;
  box-shadow:
    inset 0 1px 0 rgba(181,255,200,.26),
    inset 0 -1px 0 rgba(2,23,11,.28),
    0 0 0 1px rgba(4,89,34,.22),
    0 7px 30px rgba(0,0,0,.28),
    0 0 27px rgba(0,255,105,.20) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
/* The composer parent is a layout wrapper, not a second glass pane. */
.composer-parent,
[data-testid="composer"],
[data-testid="composer-footer-actions"] {
  background-color: transparent !important;
  border-color: transparent !important;
  box-shadow: none !important;
}
#composer-background > div,
[data-testid="composer-background"] > div {
  background-color: transparent !important;
}
#prompt-textarea,
[contenteditable="true"][role="textbox"],
[contenteditable="true"].ProseMirror,
textarea, input[type="text"], input[type="search"] {
  color: #effff3 !important;
  caret-color: #38ff82 !important;
}
#composer-background #prompt-textarea,
#composer-background [contenteditable="true"][class*="ProseMirror"],
[data-testid="composer-background"] [contenteditable="true"] {
  background-color: transparent !important;
}
#prompt-textarea:focus, [contenteditable="true"][role="textbox"]:focus,
textarea:focus, input:focus {
  outline-color: rgba(0,255,102,.77) !important;
}
#composer-background:focus-within,
[data-testid="composer-background"]:focus-within {
  border-color: rgba(115,255,166,.95) !important;
  box-shadow:
    inset 0 1px 0 rgba(181,255,200,.32),
    0 0 0 1px rgba(0,255,102,.28),
    0 0 34px rgba(0,255,102,.27) !important;
}
#prompt-textarea[contenteditable="true"]:empty:before,
[contenteditable="true"][data-placeholder]:empty:before,
#prompt-textarea::placeholder,
textarea::placeholder {
  color: #a6efbb !important;
  opacity: 1 !important;
}

/* 06. Chat transcript: glass message panels for both 2026 layouts.
   Older ChatGPT uses data-message-author-role and .user-message-bubble-color.
   The newer app shell uses data-content-search-unit-key and
   data-user-message-bubble. Style the INNER user bubble to remove blue. */

/* Layout wrappers stay clear: one glass panel per actual user message. */
[data-message-author-role="user"],
[data-content-search-unit-key$=":user"] {
  background: transparent !important;
  background-image: none !important;
  border: 0 !important;
  box-shadow: none !important;
}

/* USER: replace the opaque blue bubble with a green frosted-glass surface. */
body .user-message-bubble-color,
body [data-user-message-bubble="true"] {
  background: linear-gradient(140deg,
    rgba(22,116,60,.45) 0%,
    rgba(7,64,35,.56) 48%,
    rgba(2,29,18,.69) 100%) !important;
  background-color: rgba(3,49,27,.58) !important;
  border: 1px solid rgba(81,255,142,.59) !important;
  border-radius: 19px 19px 7px 19px !important;
  box-shadow:
    inset 0 1px 0 rgba(180,255,202,.22),
    0 5px 19px rgba(0,0,0,.20),
    0 0 17px rgba(0,255,102,.12) !important;
  color: #e0ffeb !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* Text and any inner color utility must not reintroduce a blue overlay. */
body .user-message-bubble-color .whitespace-pre-wrap,
body [data-user-message-bubble="true"] .whitespace-pre-wrap {
  color: #e0ffeb !important;
  background-color: transparent !important;
}

/* ASSISTANT: one distinct, composer-like glass panel around each answer.
   The new :assistant unit contains the visible answer, while the legacy
   selector styles the earlier message wrapper. Neither targets the composer. */
body [data-message-author-role="assistant"],
body [data-content-search-unit-key$=":assistant"] {
  background: linear-gradient(135deg,
    rgba(17,92,49,.33) 0%,
    rgba(5,47,27,.45) 49%,
    rgba(1,24,14,.64) 100%) !important;
  background-color: rgba(3,39,22,.50) !important;
  border: 1px solid rgba(76,255,137,.51) !important;
  border-radius: 21px !important;
  box-shadow:
    inset 0 1px 0 rgba(178,255,199,.19),
    0 8px 24px rgba(0,0,0,.21),
    0 0 20px rgba(0,246,98,.10) !important;
  padding: 17px 21px !important;
  margin-top: 6px !important;
  margin-bottom: 9px !important;
  color: #d9ffe6 !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-sizing: border-box !important;
  min-width: 0 !important;
}

/* Keep native answer formatting, citations, tables, and code readable. */
body [data-message-author-role="assistant"] .markdown,
body [data-message-author-role="assistant"] .prose,
body [data-content-search-unit-key$=":assistant"] .markdown,
body [data-content-search-unit-key$=":assistant"] .prose {
  color: #d3fbe0 !important;
  background-color: transparent !important;
}
[data-testid^="conversation-turn-"] {
  border-color: rgba(18,185,72,.11) !important;
}
.prose, .markdown, .text-token-text-primary {
  color: #d3fbe0 !important;
}
.prose a, .markdown a, main a:not([role="button"]) {
  color: #68ffa3 !important;
  text-decoration-color: rgba(69,255,137,.65) !important;
}
.prose a:hover, .markdown a:hover, main a:hover {
  color: #b5ffd1 !important;
}

/* 07. Dropdowns, popovers, context menus, sheets and dialogs: opaque-enough glass. */
[role="menu"], [role="listbox"], [role="dialog"],
[role="alertdialog"], [role="tooltip"],
[data-testid="composer-intelligence-picker-content"],
[data-radix-menu-content], [data-radix-popper-content-wrapper] {
  background-color: rgba(1,23,10,.96) !important;
  border: 1px solid rgba(34,255,112,.41) !important;
  color: #d9ffe5 !important;
  box-shadow: 0 12px 35px rgba(0,0,0,.62), 0 0 18px rgba(0,180,67,.14) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
[role="menuitem"], [role="menuitemradio"],
[role="menuitemcheckbox"], [role="option"],
[role="tab"] {
  color: #cef9dc !important;
  border-radius: 7px !important;
}
[role="menuitem"]:hover, [role="menuitemradio"]:hover,
[role="menuitemcheckbox"]:hover, [role="option"]:hover,
[role="menuitem"][data-highlighted], [role="option"][data-highlighted],
[role="tab"][aria-selected="true"] {
  background-color: rgba(12,103,43,.72) !important;
  color: #f0fff5 !important;
}
[role="dialog"] input, [role="dialog"] textarea,
[role="dialog"] select, [role="listbox"] input {
  background-color: rgba(4,38,18,.91) !important;
  border-color: rgba(48,255,126,.42) !important;
  color: #e1ffeb !important;
}

/* 08. Buttons, chips, suggestion tiles, and active controls. */
button, [role="button"], select {
  color: #b7ffd0 !important;
}
button:hover, [role="button"]:hover {
  border-color: rgba(30,255,109,.50) !important;
}
button:focus-visible, [role="button"]:focus-visible,
a:focus-visible, input:focus-visible {
  outline: 2px solid #00ff66 !important;
  outline-offset: 2px !important;
}
[data-testid="send-button"],
button[aria-label="Send message"],
button[aria-label="Send prompt"] {
  color: #001609 !important;
  background-color: #00e95d !important;
  box-shadow: 0 0 12px rgba(0,255,102,.32) !important;
}
[data-testid="send-button"]:hover,
button[aria-label="Send message"]:hover {
  background-color: #49ff90 !important;
}
button:disabled, [role="button"][aria-disabled="true"] {
  opacity: .65 !important;
}
[class*="home-suggestion"], [data-testid*="suggestion"],
[data-testid*="prompt-starter"] {
  background-color: rgba(4,41,20,.65) !important;
  border-color: rgba(25,229,93,.30) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
[class*="home-suggestion"]:hover, [data-testid*="suggestion"]:hover,
[data-testid*="prompt-starter"]:hover {
  background-color: rgba(10,79,34,.77) !important;
  border-color: rgba(46,255,120,.68) !important;
  box-shadow: 0 0 14px rgba(0,234,88,.15) !important;
}

/* 09. Brand logo: color through currentColor plus genuine drop-shadow glow. */
a[href="/"] svg, a[href="/"] img,
[data-testid="logo"] svg, [data-testid="logo"] img,
a[aria-label="ChatGPT"] svg, nav a[aria-label="Home"] svg {
  color: #00ff66 !important;
  filter: drop-shadow(0 0 4px rgba(0,255,102,.85)) drop-shadow(0 0 12px rgba(0,255,102,.35)) !important;
}
a[href="/"] svg, [data-testid="logo"] svg {
  stroke: currentColor !important;
}
nav svg, aside svg, header button svg { color: #79ffaa !important; }

/* 10. Long-form output, code blocks and tables remain distinguishable. */
pre, .cm-editor, .cm-scroller,
pre code, .prose pre, .markdown pre {
  background-color: rgba(1,17,9,.92) !important;
  border-color: rgba(29,214,93,.30) !important;
  color: #bfffd0 !important;
}
pre, .prose pre, .markdown pre {
  border: 1px solid rgba(27,222,94,.29) !important;
  border-radius: 10px !important;
}
:not(pre) > code {
  background-color: rgba(5,57,23,.78) !important;
  color: #90ffc0 !important;
  border-radius: 4px !important;
}
.prose blockquote, .markdown blockquote {
  border-left-color: #00e85c !important;
  background-color: rgba(4,45,22,.44) !important;
}
.prose th, .prose td, .markdown th, .markdown td,
table th, table td {
  border-color: rgba(49,211,110,.28) !important;
}
table th { background-color: rgba(5,48,21,.82) !important; }
table tr:nth-child(even) { background-color: rgba(2,27,13,.38) !important; }
hr { border-color: rgba(38,241,108,.25) !important; }

/* 11. Scrollbars and form affordances. No overlays intercept mouse events. */
* { scrollbar-color: rgba(29,191,83,.53) rgba(0,18,7,.18); scrollbar-width: thin; }
input[type="checkbox"], input[type="radio"] { accent-color: #00e85c !important; }

/* 12. PLUGINS AND SCHEDULED: LEGACY-SAFE GLASS PANELS.
   Flat CSS selectors only. No relational or functional selector syntax.
   All new styles remain inside the one domain wrapper above. */

/* Directory and task-list reading surfaces. These hooks are intentionally
   scoped to plugin/scheduled/task names to avoid affecting chat messages. */
main [data-testid*="plugin-directory"],
main [data-testid*="plugin-list"],
main [data-testid*="plugin-grid"],
main [data-testid*="scheduled-list"],
main [data-testid*="schedule-list"],
main [data-testid*="automation-list"],
main [class*="plugin-directory"],
main [class*="plugin-grid"],
main [class*="scheduled-list"],
main [class*="task-list"] {
  background: linear-gradient(155deg, rgba(6, 48, 24, .48), rgba(1, 22, 12, .72)) !important;
  border: 1px solid rgba(64, 234, 119, .28) !important;
  border-radius: 20px !important;
  box-shadow: inset 0 1px 0 rgba(147, 255, 184, .10), 0 9px 30px rgba(0, 0, 0, .19) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* Plugin tiles, scheduling rows, cards and semantic list entries.
   The last few ordinary structural selectors serve as fallbacks for UI
   versions that omit data-testid attributes. */
main [data-testid*="plugin-card"],
main [data-testid*="plugin-tile"],
main [data-testid*="schedule-card"],
main [data-testid*="scheduled-task"],
main [data-testid*="task-card"],
main [data-testid*="task-row"],
main [data-testid*="automation-card"],
main [class*="plugin-card"],
main [class*="plugin-tile"],
main [class*="schedule-card"],
main [class*="task-card"],
main [class*="task-row"],
main .grid > a[href^="/plugins/"],
main .grid > a[href^="/scheduled/"],
main .grid > [class*="rounded"][class*="border"],
main article,
main [role="listitem"] {
  background: linear-gradient(143deg, rgba(12, 70, 35, .64), rgba(3, 33, 18, .82)) !important;
  background-color: rgba(2, 30, 16, .80) !important;
  color: #ddffe8 !important;
  border: 1px solid rgba(68, 245, 125, .41) !important;
  border-radius: 17px !important;
  box-shadow: inset 0 1px 0 rgba(168, 255, 193, .14), 0 6px 22px rgba(0, 0, 0, .20) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* Navigation links can double as cards on some directory layouts. */
main a[href^="/plugins/plugin_"],
main a[href^="/scheduled/"] {
  color: #c5ffda !important;
  border-color: rgba(61, 229, 117, .34) !important;
}

/* Form fields, tabs and filter controls. */
main input[type="search"],
main [role="searchbox"],
main [role="combobox"],
main [role="tablist"],
main [data-testid*="filter-bar"],
main [data-testid*="search-container"],
main [data-testid*="plugin-search"],
main [data-testid*="scheduled-search"] {
  background: rgba(2, 28, 15, .88) !important;
  color: #e0ffea !important;
  border: 1px solid rgba(61, 239, 119, .41) !important;
  border-radius: 12px !important;
  box-shadow: inset 0 1px 0 rgba(135, 255, 178, .09) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* Card typography: clear reading contrast over the CSS grid canvas. */
main [data-testid*="plugin-card"] p,
main [data-testid*="plugin-card"] small,
main [data-testid*="scheduled-task"] p,
main [data-testid*="scheduled-task"] small,
main [data-testid*="task-card"] p,
main [data-testid*="task-card"] time,
main article p,
main article time,
main [role="listitem"] p,
main [role="listitem"] time {
  color: #c9f7d9 !important;
  text-shadow: 0 1px 3px rgba(0, 0, 0, .34) !important;
}

/* Hover accent on cards only, never on icons/images as an overlay. */
main [data-testid*="plugin-card"]:hover,
main [data-testid*="scheduled-task"]:hover,
main [data-testid*="task-card"]:hover,
main [data-testid*="automation-card"]:hover,
main .grid > a[href^="/plugins/"]:hover,
main .grid > a[href^="/scheduled/"]:hover,
main [role="listitem"]:hover {
  border-color: rgba(105, 255, 154, .73) !important;
  box-shadow: inset 0 1px 0 rgba(180, 255, 198, .16), 0 8px 26px rgba(0, 0, 0, .24), 0 0 18px rgba(0, 255, 102, .14) !important;
}

/* 13. Floating viewer toolbar: clear rail, readable individual controls.
   Keep native positioning and stacking. A full-width opaque background on
   this overlay can cover the document underneath. Do not hide descendants
   or pseudo-elements: they may provide native labels and control states. */
body header[data-testid="viewer-header"] {
  background: transparent !important;
  border-color: transparent !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  color: #e5ffed !important;
  text-shadow: none !important;
}
body header[data-testid="viewer-header"] button,
body header[data-testid="viewer-header"] [class*="controlSurface-"] {
  background: #09351e !important;
  color: #e5ffed !important;
  box-shadow: none !important;
  border-color: #367e50 !important;
}
body header[data-testid="viewer-header"] button:hover {
  background: #145530 !important;
}
body header[data-testid="viewer-header"] svg {
  color: #e5ffed !important;
}

/* 14. File viewer: opaque surface and normal-flow toolbar.
   Keep native gray tokens for custom code renderers. */
body [role="tabpanel"][data-tab-id^="chatgpt-file:"] {
 --color-surface: #071b10 !important;
 --app-shell-panel-background: #071b10 !important;
 --bg-primary: #071b10 !important;
 --main-surface-primary: #071b10 !important;
 background: #071b10 !important;
 color: #d9ffe6 !important;
}
body [role="tabpanel"][data-tab-id^="chatgpt-file:"] .bg-surface,
body [role="tabpanel"][data-tab-id^="chatgpt-file:"] [data-app-shell-pane-content-viewport] {
 background: #071b10 !important;
}
body [role="tabpanel"][data-tab-id^="chatgpt-file:"] header[data-testid="viewer-header"] {
 position: relative !important;
 inset: auto !important;
 transform: none !important;
 margin-top: 0 !important;
 margin-bottom: 0 !important;
 flex-shrink: 0 !important;
}
/* Remove decorative paint without revealing hidden measurement controls. */
body [role="tabpanel"][data-tab-id^="chatgpt-file:"] header[data-testid="viewer-header"]::before,
body [role="tabpanel"][data-tab-id^="chatgpt-file:"] header[data-testid="viewer-header"]::after {
 content: none !important;
 background: none !important;
 box-shadow: none !important;
 backdrop-filter: none !important;
 -webkit-backdrop-filter: none !important;
}
}
